(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fi"] = {"ui":{"skip":"Siirry sisältöön","back":"← Takaisin AI-gileen","lang.button":"Kieli: {name}","lang.dialog":"Valitse kieli","lang.search":"Hae kieliä","lang.none":"Yksikään kieli ei täsmää","lang.notYet":"{name} ei ole vielä käännetty","theme.aria":"Vaihda vaalean ja tumman teeman välillä","theme.toLight":"Vaihda vaaleaan teemaan","theme.toDark":"Vaihda tummaan teemaan","words.underline":"Alleviivaa nämä sanat sivulla","words.underlineHelp":"Vie hiiri pisteillä alleviivatun sanan päälle tai napauta sitä, niin näet, mitä se tarkoittaa.","index.title":"AI-gile: tekoälykehitystiimisi yhdellä taululla","index.description":"AI-gile on kanban-taulu tekoälyn kanssa koodaaville tiimeille. Ne tekevät töitä, kun nukut; sinulle jää yksi lyhyt pino päätettävää, testattavaa ja hyväksyttävää.","hero.logoAlt":"AI-gile-taulun kuvake","hero.h1.html":"Tekoälykehitystiimisi yhdellä&nbsp;taululla.","hero.alpha":"🐣 Suljettu esialfa","hero.alphaTitle":"Keskeneräinen ja aikainen: kiitos kun kokeilet!","hero.lede":"Ne rakentavat, kun nukut. Herätessäsi odottaa yksi lyhyt pino: pari kysymystä, pari testattavaa, yksi tai kaksi violettia timanttia. Klikkaus, hyväksytty, ja takaisin kahvin ääreen.","dl.windows":"Windows-sovellus","dl.browser":"Käytä selaimessa","dl.soon":"Tulossa pian","dl.notify":"🔔 Kerro, kun se aukeaa","dl.notifySmall":"Alfa tai beta","hero.secondary":"Ketterää kehitystä, mutta tiimi ei koskaan tarvitse seisomapalaverin kahvia. (Seisomapalaverin se pitää silti.)","pitch.h2":"AI-gile niin monella sanalla kuin haluat","pitch.lede":"Valitse pituus yhdestä sanasta 144:ään. Jokainen pituus on oma kuvauksensa, kirjoitettu juuri sitä kokoa varten. Vedä liukusäädintä tai käytä nuolinäppäimiä.","pitch.rangeLabel":"Pituus sanoina","pitch.dice":"🎲 toinen versio","pitch.words.one":"{n} sana","pitch.words.other":"{n} sanaa","pitch.letters.one":"{n} kirjain","pitch.letters.other":"{n} kirjainta","pitch.chars.one":"{n} merkki","pitch.chars.other":"{n} merkkiä","count.line.html.one":"{n} kortti taululla juuri nyt","count.line.html.other":"{n} korttia taululla juuri nyt","features.aria":"Mitä se tekee","f.pile.h":"Yksi pino sinulle","f.pile.html":"<b>Sinulle</b> kokoaa kaiken, mikä odottaa sinua, kaikista projekteista: kysymykset, testattavat asiat ja tehtävät, jotka vain ihminen voi hoitaa. Jonosi kertoo, mikä on seuraavana ja kuinka kauan se vie.","f.sleep.h":"Tiimit, jotka tekevät töitä, kun nukut","f.sleep.p":"Jokaisella projektilla on vetäjä ja tekoälyagenttien tiimi. Kommentoi korttia, niin tiimi herää, tekee työn ja palauttaa sen ohjeineen, joita väsynytkin ihminen jaksaa seurata.","f.tester.h":"Tekoälytestaaja tarkistaa ensin","f.tester.p":"Ennen kuin mikään pääsee sinulle asti, testaaja käy ohjeet läpi sovelluksen kopiossa ja näyttää näkemänsä kuvakaappauksen kanssa. Selaa läpimenneet ja hyväksy yhdellä klikkauksella.","f.proof.h":"Todisteita, ei lupauksia","f.proof.p":"Jokainen luovutus näyttää, mikä muuttui: tiedostot, diffin ja kuvakaappaukset. Sinun ei tarvitse availla jokaista sovellusta nähdäksesi, onko työ valmis.","f.chat.h":"Juttele vetäjiesi kanssa","f.chat.p":"Discord-tyylinen palkki: yksi kuvake per projekti, violetit timantit sille, mikä tarvitsee sinua. Lähetä vetäjälle idea; hän tekee siitä kortit ja suunnitelman sekä ✅ Go-painikkeen.","f.tidy.h":"Siivoaa itse itsensä","f.tidy.p":"Toisiinsa liittyvät kortit yhdistyvät, sekavat otsikot korjataan, ja tokenien tarkistus pitää koodin kevyenä. Vähemmän vaihdettavaa, vähemmän mietittävää.","f.private.h":"Sinun, omalla koneellasi","f.private.li1":"Taulu toimii omalla koneellasi ja vastaa vain sinulle.","f.private.li2":"Ihmisten väliset yksityisviestit on salattu päästä päähän.","f.private.li3":"Ei tilejä, ei seurantaa, ei evästeitä.","f.lang.h":"Omalla kielelläsi","f.lang.p":"Yli 120 kieltä hollannista, kymristä ja japanista merirosvoon, Yodaan ja klingoniin, ja nopea paluu englantiin kehittäjien sanoja varten.","tl.aria":"Aikajana ensimmäisestä keskustelusta tiekarttaan","tl.h2":"Ensimmäisestä keskustelusta seuraaviin askeliin","tl.lede":"Oikeat päivämäärät ja kellonajat omalla aikavyöhykkeelläsi. Tämän päivän jälkeen on suunnitelma, jossa ei luvata päivämääriä.","tl.today":"Tänään","tl.planned":"suunniteltu","tl.cards.one":"{n} kortti","tl.cards.other":"{n} korttia","join.h2":"Tule mukaan","join.lede":"AI-gilea rakentaa pieni ihminen ja suuri joukko kärsivällisiä agentteja. Se on toistaiseksi yksityinen, suljettu alfa kavereiden kesken. Haluatko kokeilla, kun se aukeaa?","join.btn":"Ilmoita kiinnostuksesi","join.small":"Lähetämme sähköpostia, emme muuta","footer.tag":"AI-gile. Ei seurantaa, ei evästeitä, ei seisomapalaverin kahvia.","footer.licence":"Yrityslisenssi","footer.status":"Tila","footer.privacy":"Mitä säilytämme","form.sending":"Lähetetään…","form.failed":"Se ei onnistunut: yritä myöhemmin uudelleen.","form.offline":"AI-gileen ei saatu yhteyttä: yritä myöhemmin uudelleen.","form.keep":"Käytämme tätä vain vastataksemme sinulle, sitten poistamme sen. Ei seurantaa, ei evästeitä.","form.keepLink":"Mitä säilytämme","interest.title":"AI-gile: kerro, kun alfa aukeaa","interest.description":"Jätä sähköpostisi, niin kuulet, kun AI-gilen suljettu alfa tai beta aukeaa.","interest.h1":"🔔 Kerro, kun se aukeaa","interest.lede":"AI-gile on suljetussa esialfassa. Jätä sähköpostisi, niin kirjoitamme kerran, kun sinulle on paikka.","interest.email":"Sähköpostisi","interest.which":"Mikä testi?","interest.alpha":"Suljettu alfa: aikainen, kulmikas, paljon muutoksia","interest.beta":"Beta: vakaampi, myöhemmin","interest.both":"Kumpi vain, kumpi aukeaa ensin","interest.submit":"Lisää minut listalle","interest.thanks":"Kiitos! Olet listalla.","licence.title":"AI-gile: yrityslisenssi","licence.description":"Käytätkö AI-gilea yrityksessäsi? Hae ilmaista yrityslisenssiä.","licence.h1":"📜 Yrityslisenssi","licence.lede":"Käytätkö AI-gilea töissä? Kerro, keitä olette ja mitä teette. Jos siitä on hyötyä, lisenssi on ilmainen.","licence.company":"Yritys","licence.website":"Verkkosivusto","licence.what":"Mitä teette","licence.how":"Miten se auttaa maailmaa","licence.email":"Sähköposti","licence.submit":"Hae","licence.thanks":"Kiitos! Vastaamme sähköpostilla.","status.title":"AI-gilen tila","status.h1":"AI-gilen tila","status.quiet":"Kaikki hiljaista","status.intro":"Toimiiko AI-gile juuri nyt? Tämä sivu tarkistaa 5 minuutin välein verkkosivuston, taulujen jakamisen, puhelut ja latauksen.","status.up":"Toimii (vastasi {ms} ms:ssa)","status.slow":"Ei vastannut viime tarkistukseen, yritetään uudelleen","status.down":"Alhaalla: ei vastannut kahteen viime tarkistukseen","status.svc.web":"Verkkosivusto","status.svc.web.offers":"Tämä sivusto: mikä AI-gile on, ja kiinnostuslomake","status.svc.boards":"Taulujen jakaminen","status.svc.boards.offers":"Julkiset taulut, viestit ystävien kesken ja kutsut","status.svc.calls":"Puhelut","status.svc.calls.offers":"Ääni, video ja näytön jakaminen AI-gilessä","status.svc.download":"Lataus","status.svc.download.offers":"Windows-asennusohjelma ja kutsulinkit","status.checking":"Tarkistetaan…","status.offline":"Tilapalveluun ei saada juuri nyt yhteyttä (yritetään uudelleen)","status.updated":"päivitetty {ago}","status.justNow":"juuri nyt","status.min":"{n} min sitten","status.hours":"{n} t sitten","status.days":"{n} pv sitten","privacy.title":"AI-gile: mitä säilytämme","privacy.h1":"Mitä säilytämme","privacy.lede":"Lyhyesti: vain sen, minkä lähetät meille, eikä kauan.","privacy.only":"Vain sen, minkä lähetät meille: mitä kirjoitat lomakkeeseen, kuten sähköpostiosoitteesi. Ei mitään muuta sinusta.","privacy.sealed":"Se sinetöidään, jotta palvelimemme ei voi lukea sitä: selaimessasi ennen kuin se lähtee (vanhemmassa selaimessa heti kun se saapuu). Vain oma taulumme voi avata sen.","privacy.server":"Se poistetaan palvelimelta heti, kun se saapuu taulullemme. Kaikki, mikä on siellä yhä 30 päivän jälkeen, poistetaan joka tapauksessa.","privacy.board":"Säilytämme sitä taulullamme vain siihen asti, kunnes olemme vastanneet sinulle, ja poistamme sen sitten sieltäkin.","privacy.none":"Ei seurantaa, ei evästeitä, ei analytiikkaa.","privacy.local":"Kielesi ja vaalean tai tumman tilan valintasi pysyvät omassa selaimessasi. Niitä ei koskaan lähetetä meille.","privacy.ask":"Haluatko, että se poistetaan aiemmin? Vastaa sähköpostiimme ja kerro siitä.","live.h2":"Katso, kun sitä rakennetaan, livenä","live.caption":"Jokainen kortti on piilotettu: näet työn muodon, et sanoja.","live.watching.one":"livenä: {n} katsoo","live.watching.other":"livenä: {n} katsoo","live.last.now":"Viimeisin kortti siirrettiin juuri nyt","live.last.min.one":"Viimeisin kortti siirrettiin {n} min sitten","live.last.min.other":"Viimeisin kortti siirrettiin {n} min sitten","live.last.hour.one":"Viimeisin kortti siirrettiin {n} tunti sitten","live.last.hour.other":"Viimeisin kortti siirrettiin {n} tuntia sitten","live.last.day.one":"Viimeisin kortti siirrettiin {n} päivä sitten","live.last.day.other":"Viimeisin kortti siirrettiin {n} päivää sitten","live.offline":"Live-taulu pitää pienen tauon. Käy katsomassa pian uudelleen.","live.cols":"Backlog|Tehtävänä|Työn alla|Tiimi tarkistaa|Sinun testattavasi|Tiimille|Valmis"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotit.","Delegoitu."]},{"n":2,"texts":["Robotit tekevät.","Agentit töihin.","Ideat valmiiksi."]},{"n":3,"texts":["Kanban robooteille.","Ideasta ominaisuus.","Ilmainen agenttikanban."]},{"n":5,"texts":["Agentit pyörittävät sinun kanban-taulua.","Sinä kirjoitat, agentit rakentavat.","Ilmainen, paikallinen, testattu, hieman hassu."]},{"n":8,"texts":["Ilmainen kanban-taulu, jolla tekoälyagentit tekevät töitä.","Kirjoita idea. Agentit rakentavat. Sinä hyväksyt.","Ketterää kehitystä yhdelle ihmiselle ja monelle kärsivälliselle robotille."]},{"n":13,"texts":["Kanban-taulu omalla koneellasi, jossa tekoälyagentit ottavat kortit hoitaakseen ja tekevät ne.","Kirjoita idea. Agenttien tiimi rakentaa sen ja testaaja tarkistaa, että se toimii.","Ilmainen, ei tilejä, ei seurantaa: yksi taulu, joukko robotteja ja sinä pomona."]},{"n":21,"texts":["AI-gile on kanban-taulu, jolla työskentelet tekoälykoodausagenttien kanssa. Ne ottavat kortit hoitaakseen ja tekevät työn; sinä vain testaat ja hyväksyt.","Jokaiselle projektille tulee oma vetäjä ja oma tekoälyagenttien tiimi. Kun kommentoit mitä tahansa korttia, tiimi herää ja ryhtyy heti töihin.","Ilmainen ja henkilökohtainen tehtävätaulu, joka toimii kokonaan omalla koneellasi. Työt tekevät robotit, mutta kyllä-sanojana olet aina sinä."]},{"n":34,"texts":["Laitat ideasi taululle yksi kerrallaan. Tekoälyagenttien tiimi muuttaa ne toimiviksi ominaisuuksiksi, testaa ne ja palauttaa ne sinulle ohjeineen, joilla pääset kokeilemaan. Mikään ei ole valmista ennen kuin sinä niin sanot.","AI-gile on kotitekoinen kanban-taulu, jonka Rich rakensi saaden paljon apua juuri niiltä agenteilta, joita se nyt hallitsee. Se on ilmainen, toimii omalla koneellasi ja jaetaan kavereille. Sitä ei myydä kenellekään.","Kuvittele ihan tavallinen kanban-taulu, jonka sarakkeet kulkevat Backlogista aina Valmiiksi, paitsi että kortit ottavat hoitaakseen tekoälyagentit. Ne kertovat edistymisestään, kysyvät neuvoa jumiutuessaan ja odottavat aina sinun lupaasi."]},{"n":55,"texts":["AI-gile on kanban-taulu, jonka tiimi koostuu tekoälyagenteista. Jokaisella projektilla on vetäjä, joka suunnittelee työn, sekä auttajia, jotka rakentavat sen. Kun ominaisuus on valmis, tekoälytestaaja kokeilee sitä ja ottaa kuvakaappauksen. Sitten se putoaa sinun omaan pinoosi. Hyväksy se tai kirjoita kommentti, niin agentit tekevät sen uusiksi.","Se alkoi yhden ihmisen keinona pysyä perillä monesta tekoälykoodausistunnosta yhtä aikaa, ja kasvoi vähitellen kunnolliseksi tauluksi. Se toimii omalla koneellasi, ei vaadi tiliä eikä seuraa sinua mitenkään. Se on ilmainen kavereille ja kaikille uteliaille. Se on myös vielä keskeneräinen, joten varaudu särmiin ja pieniin yllätyksiin.","Tässä rehellinen versio. Ideat sinun täytyy yhä keksiä itse, ja tulokset sinun täytyy yhä tarkistaa itse. AI-gile hoitaa kaiken siltä väliltä: se pitää kortit järjestyksessä, herättää oikean agentin, kun kommentoit, näyttää tarkasti mitä on muuttunut ja kokoaa kaiken yhteen lyhyeen pinoon, jonka sinä käyt läpi."]},{"n":89,"texts":["AI-gile on ilmainen kanban-taulu, jota pyörität omalla koneellasi. Ihmisten sijaan jokaisella projektilla on tekoälyagenttien tiimi: vetäjä, joka muuttaa ideasi korteiksi ja suunnitelmaksi, sekä auttajat, jotka ottavat kortit hoitaakseen tärkeysjärjestyksessä. Kun jotain on rakennettu, tekoälytestaaja käy testiohjeet läpi ja näyttää sinulle, mitä se näki. Sen jälkeen työ odottaa yhdessä pinossa, jonka nimi on Sinulle. Voit hyväksyä sen, tai voit kirjoittaa kommentin, jolloin tiimi yrittää uudelleen. Mikään ei koskaan päädy sarakkeeseen Valmis ilman sinua.","Tässä muutama ominaisuus, joita et ehkä osaa odottaa. Yövahti pitää Tehtävänä-sarakkeen täynnä sillä aikaa, kun nukut, ja valitsee kortteja, jotka eivät tarvitse sinun vastaustasi. Tokenilaskuri näyttää, kuinka paljon agentit ovat käyttäneet tänään ja tällä viikolla, ja Ei tokeneita -tila käskee niitä lopettamaan kuluttamisen. Voit lähettää viestejä kavereille, ja yksityisviestit on salattu päästä päähän. Taulu puhuu noin 120 kieltä, esimerkiksi hollantia, flaamia, merirosvoa ja klingonia. Mikään tästä ei maksa penniäkään, eikä kukaan yritä myydä sitä sinulle.","AI-gile on pieni henkilökohtainen projekti eikä mikään yritys. Rich halusi pitää huolta useasta tekoälykoodausprojektista ilman, että hänen pitää availla jokaista sovellusta erikseen tarkistaakseen tilanteen. Niinpä hän ja agentit rakensivat tätä varten taulun ja käyttivät sitä sitten loppuosan rakentamiseen. Se on suljetussa esialfassa, mikä tarkoittaa, että se toimii enimmäkseen, ja vain kourallisella kavereita. Hinnastosivua, uutiskirjettä tai kasvusuunnitelmaa ei ole. Jos tämä kuulostaa hyödylliseltä, voit pyytää päästä kokeilemaan, kun se aukeaa vähän laajemmalle."]},{"n":144,"texts":["AI-gile on kanban-taulu yhdelle ihmiselle ja monelle tekoälyagentille. Se toimii omalla koneellasi ja on täysin ilmainen. Lisäät taululle projekteja, ja jokaiselle projektille tulee oma vetäjä ja pieni tiimi. Juttelet vetäjän kanssa vähän Discordin tapaan ja kerrot idean. Vetäjä muuttaa sen korteiksi ja suunnitelmaksi ja odottaa sitten, että painat Go-painiketta. Tiimi käy kortit läpi tärkeysjärjestyksessä käyttäen yksinkertaista komentoriviä, joka on tehty nimenomaan kielimalleja varten. Ennen kuin mikään palaa sinulle, tekoälytestaaja käy ohjeet läpi sovelluksen kopiossa ja liittää mukaan kuvakaappauksen. Valmis työ päätyy sinun pinoosi, ja mukana ovat muuttuneet tiedostot sekä diff. Voit hyväksyä työn, tai voit jättää kommentin, jolloin tiimi herää ja yrittää uudelleen. Vain sinä voit siirtää kortin sarakkeeseen Valmis. Mitään ei siis tapahdu selkäsi takana, eikä mikään ole valmista, ennen kuin olet itse katsonut sitä.","Päivä AI-gilen kanssa, suunnilleen näin. Illalla jätät muutaman kommentin: tämä painike on väärässä paikassa, tuo lista pitäisi lajitella, voisiko tähän saada tumman teeman. Sitten menet nukkumaan. Agentit lukevat kommentit, tekevät muutokset, testaavat ne ja palauttavat ne sinulle. Jos Tehtävänä-sarake alkaa tyhjentyä, yövahti täyttää sen backlogista korteilla, jotka eivät tarvitse sinun vastaustasi. Aamulla odottaa yksi lyhyt pino: pari kysymystä ja muutama kokeiltava asia, jokaisessa mukana ohjeet, joita unelias ihminen jaksaa seurata, sekä kuvakaappaus siitä, että homma toimii. Klikkailet pinon läpi, hyväksyt hyvät ja lähetät loput takaisin. Tokenilaskuri näyttää, paljonko kaikki tämä kulutti, ja Ei tokeneita -tila on olemassa laihoja viikkoja varten. Sitten syöt aamiaista, jossa agentit eivät vielä osaa auttaa. Ja sinä saat vielä kahvia ihan rauhassa.","Ensin se, mitä AI-gile ei ole. Se ei ole startup, se ei ole myytävänä, eikä kukaan kerää sinun tietojasi. Se on ilmainen taulu, joka toimii omalla koneellasi ilman tilejä, ilman seurantaa ja ilman evästeitä. Mikä se sitten on: yksi siisti paikka, jossa näet kaikki tekoälykoodausprojektisi kerralla, agenttien tiimi hoitamassa kortteja ja sinä tekemässä päätökset. Se yhdistää toisiinsa liittyvät kortit, korjaa sekavat otsikot ja pitää silmällä, pysyykö koodi kevyenä. Se puhuu noin 120 kieltä, hollannista ja flaamista aina merirosvoon ja klingoniin asti. Kaverit voivat lähettää toisilleen viestejä, yksityisesti ja salattuna. Sen ovat rakentaneet Rich ja suuri joukko kärsivällisiä agentteja, enimmäkseen sitä itseään käyttäen. Se on suljetussa esialfassa, joten se on paikoin vielä kulmikas. Jos tämä kuulostaa hauskalta, pyydä kauniisti, niin pääset ehkä mukaan jo aikaisin."]}],"quips":{"1":"Yksi sana. Rohkea. Ehkä liiankin.","3":"Kolme sanaa. Jo rehellisempi kuin useimmat tuotesivut.","8":"Kahdeksan sanaa. Vielä lyhyempi kuin seisomapalaveri.","21":"Pituudet ovat muuten story pointteja. Tietysti ovat.","55":"Viisikymmentäviisi sanaa. Kaksi korttia valmistui, kun luit tämän.","144":"Tämä oli pisin. 233:a ei ole. Agentit ovat menneet nukkumaan."}},"timeline":{"first-idea.name":"Ensimmäinen idea","first-idea.line":"Aivan ensimmäinen keskustelu, ennen kuin koodia oli olemassa.","first-board.name":"Ensimmäinen taulu","first-board.line":"Taulu, joka seuraa oman rakentamisensa etenemistä: kortit, sarakkeet, vedä ja pudota, projektit.","team-roles.name":"Tiimi ja roolit","team-roles.line":"Agenttiprofiilit, tiimipohjat, tilat ja se, kuka tekee mitä.","install.name":"Asennus ja julkaisut","install.line":"Zip, jonka kaveri osaa asentaa, itsepäivitys, kanavat ja paluu vanhaan versioon.","usage-saver.name":"Käytönsäästäjä","usage-saver.line":"Mittaa, mitä ajot maksavat, pidä koodi kevyenä ja säästä rajasi.","friends.name":"Kaverit ja jakaminen","friends.line":"Yksityisviestit, sekoitettu välitys, kutsut, roolit ja jaetut projektit.","languages.name":"Kielet","languages.line":"Jokainen näytön teksti kielitiedostossa, hollanti ja flaami ensin.","ai-tester.name":"Tekoälytestaaja","ai-tester.line":"Testaaja tarkistaa jokaisen luovutuksen ensin ja näyttää näkemänsä.","website.name":"Verkkosivusto","website.line":"aigile.lol, esittelysivu ja tämä aikajana.","streaming.name":"Chat ja striimaus","streaming.line":"Discord, Twitch, OBS, striimaajatila, GIFit ja emojit.","no-ai.name":"Ilman tekoälyä -versio","no-ai.line":"Taulu ihmisille, jotka koodaavat ilman tekoälyä, sekä julkiset taulut.","night-watch.name":"Yövahti","night-watch.line":"Vahtimies ja Scrum Master pitävät tiimit tehtävässään, kun nukut.","p-more.name":"Kaikki muu","p-more.line":"Pienempiä ideoita, jotka odottavat vielä vuoroaan.","p-android.name":"Puhelin ja Android","p-android.line":"Taulusi puhelimella, sitten natiivi Android-sovellus.","p-release.name":"Alfa ja sen jälkeen","p-release.line":"Suljettu alfa, sivusto verkkoon, sitten beta.","p-languages.name":"Lisää kieliä","p-languages.line":"Yli sata kieltä ja uppoutumistila kielenoppijoille.","p-engines.name":"Lisää tekoälymoottoreita","p-engines.line":"Valitse Claude, Codex tai Gemini agenttia kohden.","p-pro.name":"Ammattikäytännöt","p-pro.line":"Riskimerkinnät, yhdistämisportit, häiriökortit ja suojakaiteet.","p-self.name":"Sinusta huolehtiminen","p-self.line":"Väsynyt-tila, itsehoitomuistutukset ja 4:20.","p-servers.name":"Palvelimet ja skaalaus","p-servers.line":"Yleiset palvelinasetukset, roolit ja kasvun suunnittelu.","p-livestream.name":"Striimauksen lisät","p-livestream.line":"Twitch-chat, omat emojit ja julkinen suoranäkymä."},"words":{"button":"📖 Kehittäjäsanat","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Hae sanaa…","none":"Mikään sana ei täsmää.","close":"Sulje","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Projektin koodikansio ja sen koko committien historia, yleensä myös GitHubissa.","also":["repositorio","repository"]},{"id":"branch","g":"build","word":"Branch","text":"Koodin erillinen työhaara, jotta muutoksia voi tehdä koskematta päälinjaan.","also":["branchit","haara","haaran","haarat","branches"]},{"id":"commit","g":"build","word":"Commit","text":"Koodin tallennettu tilannekuva lyhyellä merkinnällä siitä, mikä muuttui. Voit aina palata johonkin niistä.","also":["commitit","commitia","commitin","commits"]},{"id":"push","g":"build","word":"Push","text":"Tallennettujen tilannekuvien (commitien) lähettäminen tältä tietokoneelta GitHubiin, jotta ne varmuuskopioituvat ja jakautuvat."},{"id":"merge","g":"build","word":"Merge","text":"Haaran muutosten yhdistäminen takaisin päälinjaan."},{"id":"pr","g":"build","word":"Pull request","text":"Pyyntö, että haaran muutokset tarkistetaan ja yhdistetään päälinjaan.","also":["PR"]},{"id":"refactor","g":"build","word":"Refaktorointi","text":"Koodin siistiminen muuttamatta sen toimintaa: pienempiä tiedostoja, selkeämpiä nimiä, vähemmän toistoa."},{"id":"bug","g":"build","word":"Bugi","text":"Jokin, mikä ei toimi niin kuin pitäisi.","also":["bugit","bugia","bugin","bug","bugs"]},{"id":"test","g":"build","word":"Testi","text":"Valmiin työn kokeilu sen tarkistamiseksi, että se tekee sen, mitä pyydettiin, ennen kuin hyväksyt sen.","also":["testit","testata","testaus","testaat","testaa","test","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Uuden version vieminen tuotantoon, esimerkiksi palvelimelle, jossa ihmiset käyttävät sitä."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ideat ja työt, joita ei ole vielä suunniteltu mukaan. Niille ei tehdä mitään, ennen kuin ne siirtyvät sarakkeeseen Tehtävänä."},{"id":"sprint","g":"team","word":"Sprintti","text":"Lyhyt työjakso (usein viikko tai kaksi), jonka aikana saatetaan valmiiksi sovittu joukko kortteja.","also":["sprintit","sprintin","sprintissä","sprint","sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Nopea tilannekatsaus: mitä kukin tiimin jäsen teki, mitä hän tekee seuraavaksi ja mikä häntä jarruttaa.","also":["standup","stand-upit","stand-upia","stand-upin"]},{"id":"kanban","g":"team","word":"Kanban","text":"Taulu, jossa on sarakkeita (Tehtävänä, Työn alla, Valmis) ja kortit siirtyvät vasemmalta oikealle työn edetessä."},{"id":"wip","g":"team","word":"WIP-raja","text":"Work in progress, eli työn alla: enimmäismäärä kortteja, jonka sarake saa sisältää, jotta tiimi saa asiat valmiiksi ennen uusien aloittamista.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agentti","text":"Tekoäly, joka työskentelee itsenäisesti tehtävän parissa: lukee koodin, tekee muutoksia, ajaa tarkistuksia ja raportoi takaisin.","also":["agentit","agentin","agenttia","agent","agents"]},{"id":"token","g":"team","word":"Token","text":"Yksikkö, jolla tekoälyn käyttö lasketaan: noin muutama kirjain luettua tai kirjoitettua tekstiä. Vähemmän tokeneita, enemmän tilausta jäljellä.","also":["tokenit","tokenia","tokenin","tokens"]},{"id":"hook","g":"team","word":"Koukku","text":"Pieni komento, joka ajetaan itsestään tiettynä hetkenä, esim. kun tekoälyistunto alkaa, jotta tiimi kuulee kommenttisi.","also":["koukut","hook","hooks"]}]}};
